#include <string>
#include <openssl/md5.h>
#include <openssl/evp.h>

std::string computeUValue(std::string const& user_password, QPDF::EncryptionData const& data)
{
    // Generate encryption key from password and encryption data
    std::string padded_password = user_password;
    while (padded_password.size() < data.getPaddingLength()) {
        padded_password += '\0';
    }

    // Compute MD5 digest
    unsigned char md5_digest[MD5_DIGEST_LENGTH];
    MD5_CTX context;
    MD5_Init(&context);
    MD5_Update(&context, padded_password.c_str(), padded_password.size());
    MD5_Update(&context, data.getID().c_str(), data.getID().size());
    MD5_Final(md5_digest, &context);

    // RC4 iteration using the encryption key
    unsigned char rc4_key[16];
    for (int i = 0; i < 16; ++i) {
        rc4_key[i] = md5_digest[i];
    }

    unsigned char rc4_output[data.getOutputLength()];
    for (int i = 0; i < data.getOutputLength(); ++i) {
        rc4_output[i] = md5_digest[i % MD5_DIGEST_LENGTH];
    }

    // Prepare the U value
    std::string u_value(reinterpret_cast<char*>(rc4_output), data.getOutputLength());

    return u_value;
}
